import sys
import math

target = "....((((((((....((..(...................)..(((...((....))...((....))........))).......))))))))))...."
n = len(target)
assert n == 100

stack = []
pairs = {}
pair_pos = set()
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j
        pair_pos.add(i)
        pair_pos.add(j)


def fold(seq):
    fc = RNA.fold_compound(seq)
    ss, mfe = fc.mfe()
    return ss, mfe


def mm(seq):
    ss, _ = fold(seq)
    return sum(1 for a, b in zip(ss, target) if a != b), ss


def pairs_of(s):
    st = []
    pr = {}
    for i, c in enumerate(s):
        if c == '(':
            st.append(i)
        elif c == ')':
            j = st.pop()
            pr[j] = i
            pr[i] = j
    return pr


def diag_positions(ss):
    tp = pairs_of(target)
    mp = pairs_of(ss)
    pos = set()
    for i in tp:
        if mp.get(i, -1) != tp[i]:
            pos.add(i)
    for i in mp:
        if tp.get(i, -1) != mp[i]:
            pos.add(i)
    return list(pos)


def base_init():
    seq = ['A'] * n
    for i in range(8):
        seq[4 + i] = 'GC'[i % 2]
        seq[95 - i] = 'CG'[i % 2]
    seq[16] = 'G'; seq[87] = 'C'
    seq[17] = 'C'; seq[86] = 'G'
    seq[20] = 'G'; seq[40] = 'C'
    seq[43] = 'G'; seq[78] = 'C'
    seq[44] = 'C'; seq[77] = 'G'
    seq[45] = 'G'; seq[76] = 'C'
    seq[49] = 'G'; seq[56] = 'C'
    seq[50] = 'C'; seq[55] = 'G'
    seq[51] = 'G'; seq[52] = 'A'; seq[53] = 'A'; seq[54] = 'A'
    seq[60] = 'G'; seq[67] = 'C'
    seq[61] = 'C'; seq[66] = 'G'
    seq[62] = 'G'; seq[63] = 'A'; seq[64] = 'A'; seq[65] = 'A'
    return ''.join(seq)


def sa(seed, iters=40000):
    rng = random.Random(seed)
    seq = list(base_init())
    for i in range(n):
        if i not in pair_pos and rng.random() < 0.3:
            seq[i] = rng.choice('ACGU')
    seq = ''.join(seq)
    cur, cur_ss = mm(seq)
    best = cur
    best_seq = seq
    T0 = 3.0
    for it in range(iters):
        T = T0 * (1 - it / iters) + 0.02
        s = list(seq)
        diag = diag_positions(cur_ss) if cur > 0 else []
        if diag and rng.random() < 0.75:
            i = rng.choice(diag)
        else:
            i = rng.randint(0, n - 1)
        if i in pair_pos:
            j = pairs[i]
            ch = rng.choice([('G', 'C'), ('C', 'G'), ('A', 'U'), ('U', 'A'), ('G', 'U'), ('U', 'G')])
            s[i] = ch[0]; s[j] = ch[1]
        else:
            s[i] = rng.choice([b for b in 'ACGU' if b != s[i]])
        ns = ''.join(s)
        nv, nss = mm(ns)
        if nv <= cur or rng.random() < math.exp(-(nv - cur) / T):
            seq = ns; cur = nv; cur_ss = nss
            if nv < best:
                best = nv; best_seq = ns
                if best == 0:
                    return best_seq, 0
    return best_seq, best


overall_best = None
overall_d = 999
for s in range(1000):
    sq, d = sa(s)
    if d < overall_d:
        overall_d = d
        overall_best = sq
        sys.stdout.write(f"seed {s} dist={d}\n")
        sys.stdout.flush()
    if overall_d == 0:
        break

sys.stdout.write(f"FINAL dist={overall_d}\n{overall_best}\n")
sys.stdout.flush()

